            best_order = current[:]
            best_score = self._score_order(cells, best_order)[0]

            for permutation in itertools.permutations(window):
                trial = current[:]
                trial[start:start + 4] = permutation
                trial_score = self._score_order(cells, trial)[0]

                if trial_score > best_score:
                    best_score = trial_score
                    best_order = trial

            current = best_order

        return current

    def _refine_leaf(self, cells, rows, order) -> List[int]:
        """Perform two bounded exact adjacent-swap passes on a group suffix."""
        if len(order) < 2 or len(rows) < 2:
            return list(order)

        current = list(order)
        score = self._group_score(cells, rows, current)
        limit = min(12, len(current) - 1)

        for reverse in (False, True):
            positions = (
                range(limit - 1, -1, -1)
                if reverse else range(limit)
            )

            for position in positions:
                trial = current[:]
                trial[position], trial[position + 1] = (
                    trial[position + 1],
                    trial[position],
                )
                trial_score = self._group_score(cells, rows, trial)

                if trial_score > score:
                    current = trial
                    score = trial_score

        return current

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Partition by the strongest field and choose suffixes per partition."""
        n, m = cells.shape

        if m <= 1:
            return [list(range(m)) for _ in range(n)]

        lead = max(
            range(m),
            key=lambda column: (
                self._repeat_mass(cells, column),
                -column,
            ),
        )

        groups = {}
        for row in range(n):
            groups.setdefault(cells[row, lead], []).append(row)

        remaining = [
            column for column in range(m)
            if column != lead
        ]
        result = [None] * n

        for rows in groups.values():
            ranked = []

            for column in remaining:
                counts = {}
                for row in rows:
                    value = cells[row, column]
                    counts[value] = counts.get(value, 0) + 1

                mass = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                ranked.append((mass, column))

            ranked.sort(key=lambda item: (-item[0], item[1]))
            suffix = [column for _, column in ranked]
            suffix = self._refine_leaf(cells, rows, suffix)
            full_order = [lead] + suffix

            for row in rows:
                result[row] = full_order[:]

        return result

    def _candidate(self, cells, orders):
        """Serialize, score, and deterministically sort one candidate."""
        strings = [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate marginal, enumerated-window, and conditional candidates losslessly."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        global_a = self._global_order(cells, 0)
        global_b = self._enumerated_global(cells)
        conditional = self._conditional_orders(cells)

        candidates = [
            [global_a[:] for _ in range(n)],
            [global_b[:] for _ in range(n)],
            conditional,
        ]

        best = None

        for orders in candidates:
            if orders and all(order == orders[0] for order in orders):
                score, strings, row_order = self._score_order(
                    cells, orders[0]
                )
            else:
                score, strings, row_order = self._candidate(
                    cells, orders
                )

            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, _, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, column]
                for column in source_order
            ]
            column_orders.append([
                df.columns[column]
                for column in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders
